func (b *DeliveryCardBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(DeliveryCard{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	DeliveryCardReset((*DeliveryCard)(p))
	return true
}
